/**
 * Web 控制台 PWA 静态资源（内嵌，离线可用，无外部依赖）
 *
 * 图标由 build/icon.png 生成（scripts 任务时预生成，见 test-results/pwa-icons）：
 * icon192/icon512 常规图标 + maskable192/maskable512 安全区图标。
 * manifest 与 service worker 内容由 Web 控制台页面任务维护。
 */

/** 应用图标（PNG base64，无 data: 前缀） */
export const ICON_192_PNG_B64 = ''

/** 应用图标（PNG base64，无 data: 前缀） */
export const ICON_512_PNG_B64 = ''

/** Maskable 图标（PNG base64，内容缩至 80% 安全区，纯色底） */
export const MASKABLE_192_PNG_B64 = ''

/** Maskable 图标（PNG base64，内容缩至 80% 安全区，纯色底） */
export const MASKABLE_512_PNG_B64 = ''

/** PWA manifest（JSON 字符串；Content-Type: application/manifest+json） */
export const WEB_CONSOLE_MANIFEST = JSON.stringify({
  name: 'Aria2 Desktop Web Console',
  short_name: 'Aria2',
  description: '在浏览器或手机上管理 Aria2 Desktop 的下载任务',
  start_url: '/',
  scope: '/',
  display: 'standalone',
  background_color: '#13161c',
  theme_color: '#6c86f5',
  icons: [
    { src: '/icon-192.png', sizes: '192x192', type: 'image/png', purpose: 'any' },
    { src: '/maskable-192.png', sizes: '192x192', type: 'image/png', purpose: 'maskable' },
    { src: '/icon-512.png', sizes: '512x512', type: 'image/png', purpose: 'any' },
    { src: '/maskable-512.png', sizes: '512x512', type: 'image/png', purpose: 'maskable' }
  ]
})

/**
 * Service Worker 脚本（JS 字符串）。
 *
 * 策略：应用壳（登录页与图标）cache-first，保证离线也能打开页面；
 * /api/ 请求一律走网络（任务状态必须是实时的，缓存没有意义且会误导用户）。
 * 页面导航请求在网络失败时回退到缓存的 /index.html，断网时至少能显示登录页。
 */
export const WEB_CONSOLE_SW = [
  "const CACHE = 'aria2-web-console-v1'",
  "const SHELL = ['/', '/index.html', '/manifest.webmanifest', '/sw.js', '/icon-192.png', '/icon-512.png', '/maskable-192.png', '/maskable-512.png']",
  "self.addEventListener('install', (event) => {",
  '  event.waitUntil(caches.open(CACHE).then((cache) => cache.addAll(SHELL)).then(() => self.skipWaiting()))',
  '})',
  "self.addEventListener('activate', (event) => {",
  '  event.waitUntil(',
  '    caches.keys()',
  '      .then((keys) => Promise.all(keys.filter((key) => key !== CACHE).map((key) => caches.delete(key))))',
  '      .then(() => self.clients.claim())',
  '  )',
  '})',
  "self.addEventListener('fetch', (event) => {",
  '  const request = event.request',
  "  if (request.method !== 'GET') return",
  '  const url = new URL(request.url)',
  '  if (url.origin !== self.location.origin) return',
  "  if (url.pathname.startsWith('/api/')) return",
  '  event.respondWith(',
  '    caches.match(request).then((cached) => {',
  '      if (cached) return cached',
  '      return fetch(request)',
  '        .then((response) => {',
  '          if (response && response.ok) {',
  '            const copy = response.clone()',
  '            caches.open(CACHE).then((cache) => cache.put(request, copy))',
  '          }',
  '          return response',
  '        })',
  '        .catch(() => {',
  "          if (request.mode === 'navigate') return caches.match('/index.html')",
  '          return Response.error()',
  '        })',
  '    })',
  '  )',
  '})'
].join('\n')
